\documentclass[10pt, letterpaper]{article}

\usepackage[
    ignoreheadfoot,
    top=2 cm,
    bottom=2 cm,
    left=2 cm,
    right=2 cm,
    footskip=1.0 cm,
]{geometry}
\usepackage{titlesec}
\usepackage{tabularx}
\usepackage{array}
\usepackage[dvipsnames]{xcolor}
\definecolor{primaryColor}{RGB}{0, 79, 144}
\usepackage{enumitem}
\usepackage{fontawesome5}
\usepackage{amsmath}
\usepackage[
    pdftitle={John Doe's CV},
    pdfauthor={John Doe},
    pdfcreator={LaTeX with RenderCV},
    colorlinks=true,
    urlcolor=primaryColor
]{hyperref}
\usepackage[pscoord]{eso-pic}
\usepackage{calc}
\usepackage{bookmark}
\usepackage{lastpage}
\usepackage{changepage}
\usepackage{paracol}
\usepackage{ifthen}
\usepackage{needspace}
\usepackage{iftex}

\ifPDFTeX
    \input{glyphtounicode}
    \pdfgentounicode=1
    \usepackage[utf8]{inputenc}
    \usepackage{lmodern}
\fi

\AtBeginEnvironment{adjustwidth}{\partopsep0pt}
\pagestyle{empty}
\setcounter{secnumdepth}{0}
\setlength{\parindent}{0pt}
\setlength{\topskip}{0pt}
\setlength{\columnsep}{0cm}
\makeatletter
\let\ps@customFooterStyle\ps@plain
\patchcmd{\ps@customFooterStyle}{\thepage}{
    \color{gray}\textit{\small }
}{}{}
\makeatother
\pagestyle{customFooterStyle}

\titleformat{\section}{\needspace{4\baselineskip}\bfseries\large}{}{0pt}{}[\vspace{1pt}\titlerule]

\titlespacing{\section}{
    -1pt
}{
    0.3 cm
}{
    0.2 cm
}

\renewcommand\labelitemi{$\circ$}
\newenvironment{highlights}{
    \begin{itemize}[
        topsep=0.10 cm,
        parsep=0.10 cm,
        partopsep=0pt,
        itemsep=0pt,
        leftmargin=0.4 cm + 10pt
    ]
}{
    \end{itemize}
}

\newenvironment{highlightsforbulletentries}{
    \begin{itemize}[
        topsep=0.10 cm,
        parsep=0.10 cm,
        partopsep=0pt,
        itemsep=0pt,
        leftmargin=10pt
    ]
}{
    \end{itemize}
}

\newenvironment{onecolentry}{
    \begin{adjustwidth}{
        0.2 cm + 0.00001 cm
    }{
        0.2 cm + 0.00001 cm
    }
}{
    \end{adjustwidth}
}

\newenvironment{twocolentry}[2][]{
    \onecolentry
    \def\secondColumn{#2}
    \setcolumnwidth{\fill, 4.5 cm}
    \begin{paracol}{2}
}{
    \switchcolumn \raggedleft \secondColumn
    \end{paracol}
    \endonecolentry
}

\newenvironment{header}{
    \setlength{\topsep}{0pt}\par\kern\topsep\centering\linespread{1.5}
}{
    \par\kern\topsep
}

\newcommand{\placelastupdatedtext}{
  \AddToShipoutPictureFG*{
    \put(
        \LenToUnit{\paperwidth-2 cm-0.2 cm+0.05cm},
        \LenToUnit{\paperheight-1.0 cm}
    ){\vtop{{\null}\makebox[0pt][c]{
        \small\color{gray}\textit{}\hspace{\widthof{}}
    }}}
  }
}

\let\hrefWithoutArrow\href

\renewcommand{\href}[2]{\hrefWithoutArrow{#1}{\ifthenelse{\equal{#2}{}}{ }{#2 }\raisebox{.15ex}{\footnotesize \faExternalLink*}}}

\begin{document}
    \newcommand{\AND}{\unskip
        \cleaders\copy\ANDbox\hskip\wd\ANDbox
        \ignorespaces
    }
    \newsavebox\ANDbox
    \sbox\ANDbox{}

    \placelastupdatedtext
    \begin{header}
        \textbf{\fontsize{24 pt}{24 pt}\selectfont John Doe}

        \vspace{0.3 cm}

        \normalsize
        \mbox{{\color{black}\footnotesize\faMapMarker*}\hspace*{0.13cm}Your Location}
        \kern 0.25 cm
        \AND
        \kern 0.25 cm
        \mbox{\hrefWithoutArrow{mailto:youremail@yourdomain.com}{\color{black}{\footnotesize\faEnvelope[regular]}\hspace*{0.13cm}youremail@yourdomain.com}}
        \kern 0.25 cm
        \AND
        \kern 0.25 cm
        \mbox{\hrefWithoutArrow{tel:+90-541-999-99-99}{\color{black}{\footnotesize\faPhone*}\hspace*{0.13cm}0541 999 99 99}}
        \kern 0.25 cm
        \AND
        \kern 0.25 cm
        \mbox{\hrefWithoutArrow{https://yourwebsite.com/}{\color{black}{\footnotesize\faLink}\hspace*{0.13cm}yourwebsite.com}}
        \kern 0.25 cm
        \AND
        \kern 0.25 cm
        \mbox{\hrefWithoutArrow{https://linkedin.com/in/yourusername}{\color{black}{\footnotesize\faLinkedinIn}\hspace*{0.13cm}yourusername}}
        \kern 0.25 cm
        \AND
        \kern 0.25 cm
        \mbox{\hrefWithoutArrow{https://github.com/yourusername}{\color{black}{\footnotesize\faGithub}\hspace*{0.13cm}yourusername}}
    \end{header}

    \vspace{0.3 cm - 0.3 cm}

    \section{Education}

    \begin{twocolentry}{
        \textit{Sept 2000 – May 2005}}
        \textbf{University of Pennsylvania}

        \textit{BS in Computer Science}
    \end{twocolentry}

    \vspace{0.10 cm}
    \begin{onecolentry}
        \begin{highlights}
            \item GPA: 3.9/4.0
            \item \textbf{Coursework:} Computer Architecture, Comparison of Learning Algorithms, Computational Theory
        \end{highlights}
    \end{onecolentry}

    \section{Experience}

    \begin{twocolentry}{
        \textit{Cupertino, CA}
        \textit{June 2005 – Aug 2007}}
        \textbf{Software Engineer}
        \textit{Apple}
    \end{twocolentry}

    \vspace{0.10 cm}
    \begin{onecolentry}
        \begin{highlights}
            \item Reduced time to render user buddy lists by 75\% by implementing a prediction algorithm
            \item Integrated iChat with Spotlight Search by creating a tool to extract metadata from saved chat transcripts and provide metadata to a system-wide search database
            \item Redesigned chat file format and implemented backward compatibility for search
        \end{highlights}
    \end{onecolentry}

    \vspace{0.2 cm}

    \begin{twocolentry}{
        \textit{Redmond, WA}
        \textit{June 2003 – Aug 2003}}
        \textbf{Software Engineer Intern}
        \textit{Microsoft}
    \end{twocolentry}

    \vspace{0.10 cm}
    \begin{onecolentry}
        \begin{highlights}
            \item Designed a UI for the VS open file switcher (Ctrl-Tab) and extended it to tool windows
            \item Created a service to provide gradient across VS and VS add-ins, optimizing its performance via caching
            \item Built an app to compute the similarity of all methods in a codebase, reducing the time from $\mathcal{O}(n^2)$ to $\mathcal{O}(n \log n)$
            \item Created a test case generation tool that creates random XML docs from XML Schema
            \item Automated the extraction and processing of large datasets from legacy systems using SQL and Perl scripts
        \end{highlights}
    \end{onecolentry}

    \section{Publications}

    \begin{samepage}
        \begin{twocolentry}{
            Jan 2004
        }
            \textbf{3D Finite Element Analysis of No-Insulation Coils}

            \vspace{0.10 cm}

            \mbox{Frodo Baggins}, \mbox{\textbf{\textit{John Doe}}}, \mbox{Samwise Gamgee}
        \end{twocolentry}

        \vspace{0.10 cm}

        \begin{onecolentry}
    \href{https://doi.org/10.1109/TASC.2023.3340648}{10.1109/TASC.2023.3340648}
        \end{onecolentry}
    \end{samepage}

    \section{Projects}

    \begin{twocolentry}{
        \textit{\href{https://github.com/sinaatalay/rendercv}{github.com/name/repo}}}
        \textbf{Multi-User Drawing Tool}
    \end{twocolentry}

    \vspace{0.10 cm}
    \begin{onecolentry}
        \begin{highlights}
            \item Developed an electronic classroom where multiple users can simultaneously view and draw on a "chalkboard" with each person's edits synchronized
            \item Tools Used: C++, MFC
        \end{highlights}
    \end{onecolentry}

    \vspace{0.2 cm}

    \begin{twocolentry}{
        \textit{\href{https://github.com/sinaatalay/rendercv}{github.com/name/repo}}}
        \textbf{Synchronized Desktop Calendar}
    \end{twocolentry}

    \vspace{0.10 cm}
    \begin{onecolentry}
        \begin{highlights}
            \item Developed a desktop calendar with globally shared and synchronized calendars, allowing users to schedule meetings with other users
            \item Tools Used: C\#, .NET, SQL, XML
        \end{highlights}
    \end{onecolentry}

    \vspace{0.2 cm}

    \begin{twocolentry}{
        2002}
        \textbf{Custom Operating System}
    \end{twocolentry}

    \vspace{0.10 cm}
    \begin{onecolentry}
        \begin{highlights}
            \item Built a UNIX-style OS with a scheduler, file system, text editor, and calculator
            \item Tools Used: C
        \end{highlights}
    \end{onecolentry}

    \section{Technologies}

    \begin{onecolentry}
        \textbf{Languages:} C++, C, Java, Objective-C, C\#, SQL, JavaScript
    \end{onecolentry}

    \vspace{0.2 cm}

    \begin{onecolentry}
        \textbf{Technologies:} .NET, Microsoft SQL Server, XCode, Interface Builder
    \end{onecolentry}

\end{document}

